package e.e.a;public class HistorySortRulesTest{static int n;static void check(boolean b){n++;if(!b)throw new AssertionError();}public static void main(String[] args){long expected=HistorySortRules.watched("2026年10月13日 23時07分 視聴 0回視聴");check(expected>0);check(expected==HistorySortRules.watched("2026-10-13 23:07 Watched 0 times"));check(expected==HistorySortRules.watched("2026/10/13 23:07:00"));check(expected==HistorySortRules.watched("2026-10-13T23:07:00+09:00"));check(expected==HistorySortRules.watched("<b>2026年10月13日 23時07分</b> 視聴"));check(HistorySortRules.watched("2026年10月12日 23時07分")<expected);check(HistorySortRules.watched("2026年10月14日 23時07分")>expected);check(HistorySortRules.watched("bad")==0&&HistorySortRules.watched(null)==0);check(HistorySortRules.watched("2026-02-30 23:07")==0);check(HistorySortRules.compare(expected,expected-1,2,0,false)<0);check(HistorySortRules.compare(expected,expected-1,2,0,true)>0);check(HistorySortRules.compare(0,expected,0,2,false)>0&&HistorySortRules.compare(0,expected,0,2,true)>0);check(HistorySortRules.compare(0,0,0,1,true)<0);System.out.println("History sorting dates: "+n+" format and boundary checks passed");}}
